function UIPlayerCreateDialog:Awake()
    local argument = self.controller.Argument.parameters
    self.plotIds = argument.args.plotIds
    self.opId = argument.args.id
    self.continueIndex = argument.args.continueIndex

    self.animator = KTool.GetComponent(self.Root.gameObject, typeof(Animator))
    local button = self.ButtonCreate:GetComponent(typeof(Button))
    SetButtonAction(button, Bind(self, self.NewRoleAction))
    local backButton = self.BackButton:GetComponent(typeof(Button))
    SetButtonAction(backButton, Bind(self, self.OnBackAction))
    KTool.SetActive(self.SkipButton.gameObject, false)
    -- SetButtonAction(self.SkipButton, Bind(self, self.OnSkipButtonAction))

    -- 获取场景里面的lua脚本
    local sceneInstance = SceneManagement:GetInstance():GetSceneInstance(Constants.IdSceneSetting32)
    local GO_Scene = sceneInstance:GetCacheObjectByName('Scene')
    local chooseGender = GetLuaBehaviour(GO_Scene, "Game.Entry.ChooseGender")
    self:GetChooseGender(chooseGender.Env)
	if gameUtils.IsWindow() then
		self.EventWinSDK = Events.AddListener("WinPlayerCreateDialog", Bind(self, self.OnWinPlayerCreateDialog))
	end
	
    -- 关闭主相机
    KTool.SetActive(URPCameraController.mainCamera, false)
    -- 修改主相机参数，防止后面的剧情里露出天空盒，看到场景中的东西
    URPCameraController.mainCamera.backgroundColor = Color(0, 0, 0, 0)
    URPCameraController.mainCamera.transform.position = Vector3.New(0, 100, 100)
    URPCameraController.mainCamera.transform.rotation = Quaternion.Euler(-90, 0, 0)
end

function UIPlayerCreateDialog:OnWinPlayerCreateDialog(body)
    if not body then
        return
    end
    local type = checkNumber(body.type)
    if type == 1 then
        local playerName = self.chooseGender:GetPlayerName()
        local playerDojo = GameUtils.GetPlayerDojo()
        if playerDojo then
            if string.isEmpty(string.trim(playerName)) then
                playerName = playerDojo.playerName
            end
        end
        self:DoNewRoleAction(playerName)
    end
end

