function UIPlayerCreateDialog:OnFinalize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self.InputField) then
            if self.InputField.onValueChanged then
