            cs_coroutine.stop(self.ShowMovieUICo)
            self.ShowMovieUICo = nil
        end

        if self.ShowMovieUISecondCo then
            cs_coroutine.stop(self.ShowMovieUISecondCo)
            self.ShowMovieUISecondCo = nil
        end
		if gameUtils.IsWindow() then
			Events.RemoveListener("WinPlayerCreateDialog", self.EventWinSDK)
		end
		
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要

    end))
