function UIPlayerCreateDialog:DoNewRoleAction(playerName)
	local gender = self.chooseGender:GetGender()
	if gender == 1 then
		self.isBoy = true
	end
	--local interface = Interfaces.PlayerCreate
	local interface = Interfaces.PlayerUpName
	if self.isPreOpened then
		-- 预下载玩家已经创角过，此处更新创角数据
		interface = Interfaces.PlayerUpgrade
	end
	gameUtils.Request(interface, { playerName = playerName, gender = gender}, function(request, response)
		if checkNumber(response.errCode) == 0 then
			x_record_event('CREATE_ROLE')
			xRecord.record('1-005')
			--checkin logical
			local data = checkTable(response.data)
			local playerId = data.playerId
			local playerName = data.playerName
			---@type ECSWorldMgr
			local worldMgr = ECSWorldMgr:GetInstance()
			---@type ECSWorld
			local world = worldMgr:GetWorld(Constants.GameWorld)
			---@type ECSEntity
			local entity = world:GetEntity(Constants.PlayerEntityId)
			local playerComponent = entity:GetOrAddComp(ECSComponentType.Constants.PlayerComponent)
			if not isNull(playerComponent) then
				playerComponent.playerDojo:PlayerId(playerId)
				playerComponent.playerDojo.playerName = playerName
				playerComponent.playerDojo.gender = checkNumber(gender)
				playerComponent.playerDojo.serverTime = checkNumber(data.serverTime)
				local SDKService = import('Game.Entry.SDKService')
				local sdkService = SDKService:GetInstance()
				sdkService:CreateRole(playerId, playerName)
				sdkService:TrackReYunEvent("register",{ accountID = tostring(playerId)})
				--- checkin
				gameUtils.Request(Interfaces.PlayerCheckIn, nil, Bind(self, self.OnSuccess))
			end
            xRecord.af_internal("name_change")
            xRecord.adjust_internal({event = "newplayer01"})
            xRecord.facebook_internal("fb_mobile_tutorial_completion" , {playerId = tostring(playerComponent:GetPlayerDojo().playerId)})
		end
	end)
end

---NewRoleAction
---创角的逻辑
function UIPlayerCreateDialog:NewRoleAction()
    if isNull(self.chooseGender) then
        return
    end
    local playerName = self.chooseGender:GetPlayerName()

    local playerDojo = GameUtils.GetPlayerDojo()
    if playerDojo then
        if string.isEmpty(string.trim(playerName)) then
           playerName = playerDojo.playerName
        end
        if gameUtils.IsWindow() then
            Events.Broadcast(Constants.EventNames.WinSDK, { type = 13, startGame = false})  -- 实名认证
        else
            self:DoNewRoleAction(playerName)
        end
    else
        if string.isEmpty(playerName) then
            gameUtils.Toast(localize("请输入用户名"))
            return
        end
        if gameUtils.IsWindow() then
            Events.Broadcast(Constants.EventNames.WinSDK, { type = 13, startGame = false})  -- 实名认证
        else
            self:DoNewRoleAction(playerName)
        end
    end
end

function UIPlayerCreateDialog:OnSuccess(request, response)
    if checkNumber(response.errCode) == 0 then
        local data = checkTable(response.data)
        ---@type ECSWorldMgr
        local worldMgr = ECSWorldMgr:GetInstance()
        ---@type ECSWorld
        local world = worldMgr:GetWorld(Constants.GameWorld)
        ---@type ECSEntity
        local entity = world:GetEntity(Constants.PlayerEntityId)
        --if entity:IsCompExistsByName(ECSComponentType.Constants.PlayerComponent) then
        --    entity:RemoveComp(ECSComponentType.Constants.PlayerComponent)
        --end
        ---@type PlayerComponent
        local playerComponent = entity:GetOrAddComp(ECSComponentType.Constants.PlayerComponent)
        playerComponent:LoadPlayer(data)
        GameUtils.InstantiatePVPPrompt()
        --UIRaycastBlocker:AddCondition("FuncBeforeClosePrePanel")
        --cs_coroutine.start(function()
        --    xTry(function()
        ---@type UnityEngine.Animator
        --local anim = KTool.GetComponent(self.BtnFonfirmAnim.gameObject, typeof(Animator))
        --self.TransAnimator:Play(Animator.StringToHash("Transition"),-1)
        --anim:Play(Animator.StringToHash("Enter"), -1)
        --cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.9))---ui表现延时1.5进行下一步进入游戏
        --if not isNull(self.chooseGender) then
        --    self.chooseGender:CreateRoleSuccess()
        --end
        --cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.4))---ui表现延时1.5进行下一步进入游戏

        if not isNull(self.chooseGender) then
            self.chooseGender:DisableInputAndClick()
        end

        local gr = self.controller.gameObject:GetComponent(typeof(CS.UnityEngine.UI.GraphicRaycaster))
        if not isNull(gr) then
            gr.enabled = false
        end
        self.controller.CacheCanvas.enabled = false

        cs_coroutine.start(function()
            local IsOpenOp =  AppEngine.GetConfig("Engine.Dev", "IsOpenOp")
            if checkNumber(IsOpenOp) > 0 then
                local vo = QuestConfMgr:GetInstance():GetQuestVoById(self.opId)
                -- 创完角，继续播剩下的剧情
                MainQuestMapMgr:GetInstance().curPlotIndex = self.continueIndex
                MainQuestMapMgr:GetInstance():PlayPloting(self.plotIds, vo, function()  
                    -- 最后结束剧情，前往主界面
                    local questComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
                    --理论上可以重复改名但是没必要
                    questComponent:StoryEnterReq(self.opId, function()
                        GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {}, Constants.LoadingType.MainHome, true)
                        if self.chooseGender ~= nil then
                            self.chooseGender:TransitionScene()
                            self.chooseGender = nil
                        end
                        UIModule.CloseDialog(self.controller)
                    end)
                end, function()
                    -- 关闭选角场景相机
                    Events.Broadcast(Constants.EventNames.PLAYER_CREATE_ROLE_FINISH,self)
                end)
            else
                GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {}, Constants.LoadingType.MainHome, true)
                if self.chooseGender ~= nil then
                    self.chooseGender:TransitionScene()
                    self.chooseGender = nil
                end
                UIModule.CloseDialog(self.controller)
            end
        end)
    
        local SDKService = import('Game.Entry.SDKService')
        local sdkService = SDKService:GetInstance()
        sdkService:UploadRole(data.playerId,data.playerName)
        sdkService:TrackReYunEvent("login",{ accountID = tostring(data.playerId)})
    end
    xRecord.record("15-007")
end

